<?php
require __DIR__ . '/config.php'; $pdo=db();
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $id=(int)($_POST['id']??0); $name=trim($_POST['name']??'');
    if ($name==='') { flash('Medicine name is required.','error'); redirect('medicines.php'); }
    $values=[$name,trim($_POST['generic_name']??''),trim($_POST['category']??''),trim($_POST['strength']??''),trim($_POST['unit']??'strip'),(float)($_POST['price']??0),(float)($_POST['cost_price']??0),(int)($_POST['stock_qty']??0),(int)($_POST['reorder_level']??10),$_POST['expiry_date']?:null,(int)($_POST['supplier_id']??0)?:null];
    if ($id) { $values[]=$id; $pdo->prepare('UPDATE medicines SET name=?,generic_name=?,category=?,strength=?,unit=?,price=?,cost_price=?,stock_qty=?,reorder_level=?,expiry_date=?,supplier_id=? WHERE id=?')->execute($values); flash('Medicine updated.'); }
    else { $pdo->prepare('INSERT INTO medicines (name,generic_name,category,strength,unit,price,cost_price,stock_qty,reorder_level,expiry_date,supplier_id) VALUES (?,?,?,?,?,?,?,?,?,?,?)')->execute($values); flash('Medicine added to your inventory.'); }
    redirect('medicines.php');
}
if (isset($_GET['delete'])) { $pdo->prepare('UPDATE medicines SET active=0 WHERE id=?')->execute([(int)$_GET['delete']]); flash('Medicine archived.'); redirect('medicines.php'); }
$search=trim($_GET['q']??''); $stmt=$pdo->prepare("SELECT m.*,s.name supplier_name FROM medicines m LEFT JOIN suppliers s ON s.id=m.supplier_id WHERE m.active=1 AND (m.name LIKE ? OR m.generic_name LIKE ? OR m.category LIKE ?) ORDER BY m.name"); $like="%$search%"; $stmt->execute([$like,$like,$like]); $items=$stmt->fetchAll(); $suppliers=$pdo->query('SELECT id,name FROM suppliers WHERE active=1 ORDER BY name')->fetchAll();
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM medicines WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$pageTitle='Medicines'; require __DIR__.'/partials/header.php';
?>
<div class="welcome"><div><div class="eyebrow">CATALOGUE</div><h1>Medicine inventory</h1><p>Keep products, prices, and stock in sync.</p></div><button class="button" type="button" onclick="document.getElementById('medicine-form').scrollIntoView({behavior:'smooth'})">＋ Add medicine</button></div>
<section class="panel form-panel" id="medicine-form"><div class="panel-heading"><div><div class="eyebrow"><?= $edit?'EDIT ITEM':'NEW ITEM' ?></div><h2><?= $edit?'Update medicine':'Add a medicine' ?></h2></div></div><form method="post" class="form-grid"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Medicine name *<input name="name" required value="<?= h($edit['name']??'') ?>" placeholder="e.g. Paracetamol"></label><label>Generic name<input name="generic_name" value="<?= h($edit['generic_name']??'') ?>" placeholder="Active ingredient"></label><label>Category<input name="category" value="<?= h($edit['category']??'') ?>" placeholder="Pain relief"></label><label>Strength<input name="strength" value="<?= h($edit['strength']??'') ?>" placeholder="500 mg"></label><label>Unit<input name="unit" value="<?= h($edit['unit']??'strip') ?>" placeholder="strip / bottle"></label><label>Sell price (₹)<input type="number" step="0.01" min="0" name="price" required value="<?= h($edit['price']??'') ?>"></label><label>Cost price (₹)<input type="number" step="0.01" min="0" name="cost_price" value="<?= h($edit['cost_price']??'0') ?>"></label><label>Stock quantity<input type="number" min="0" name="stock_qty" value="<?= h($edit['stock_qty']??0) ?>"></label><label>Reorder level<input type="number" min="0" name="reorder_level" value="<?= h($edit['reorder_level']??10) ?>"></label><label>Expiry date<input type="date" name="expiry_date" value="<?= h($edit['expiry_date']??'') ?>"></label><label>Supplier<select name="supplier_id"><option value="">No supplier linked</option><?php foreach($suppliers as $s): ?><option value="<?= $s['id'] ?>" <?= ($edit['supplier_id']??'')==$s['id']?'selected':'' ?>><?= h($s['name']) ?></option><?php endforeach; ?></select></label><div class="form-actions"><button class="button" type="submit"><?= $edit?'Save changes':'Add medicine' ?></button><?php if($edit): ?><a class="button secondary" href="medicines.php">Cancel</a><?php endif; ?></div></form></section>
<section class="panel table-panel"><div class="panel-heading"><div><div class="eyebrow">PRODUCTS</div><h2><?= count($items) ?> medicines</h2></div><form class="search" method="get"><input name="q" value="<?= h($search) ?>" placeholder="Search medicines…"><button aria-label="Search">⌕</button></form></div><div class="table-wrap"><table><thead><tr><th>Medicine</th><th>Category</th><th>Supplier</th><th>Stock</th><th>Expiry</th><th class="right">Price</th><th></th></tr></thead><tbody><?php foreach($items as $m): ?><tr><td><b><?= h($m['name']) ?></b><small class="subline"><?= h(trim($m['strength'].' · '.$m['generic_name'],' ·')) ?></small></td><td><?= h($m['category']?:'—') ?></td><td><?= h($m['supplier_name']?:'—') ?></td><td><span class="stock-badge <?= $m['stock_qty']<=$m['reorder_level']?'warning':'' ?>"><?= (int)$m['stock_qty'] ?> <?= h($m['unit']) ?></span></td><td><?= $m['expiry_date']?h(date('M Y',strtotime($m['expiry_date']))):'—' ?></td><td class="right amount"><?= money($m['price']) ?></td><td class="row-actions"><a href="?edit=<?= $m['id'] ?>">Edit</a><a class="danger-link" href="?delete=<?= $m['id'] ?>" data-confirm="Archive this medicine?">Archive</a></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="7" class="empty">No matching medicines found.</td></tr><?php endif; ?></tbody></table></div></section>
<?php require __DIR__.'/partials/footer.php'; ?>
